// @concept CONCEPT-taf-v1-004-01-the-artifacts

import * as fs from "node:fs";
import * as path from "node:path";
import { Locator, Page } from "@playwright/test";
import { tafJournal } from "./taf_journal";

interface Row { name: string; status: string; expected: string; actual: string; }
const ROWS: Row[] = [];

export function goldensDir(): string {
  return process.env["TAF_GOLDENS"] || "goldens";
}

function diffHtml(name: string, expected: string, actual: string): string {
  return `<!doctype html><meta charset=utf-8><title>diff ${name}</title>`
    + `<h2>${name}</h2><table><tr><th>Expected</th><th>Actual</th></tr><tr>`
    + `<td><img src="file://${expected}" style="max-width:48vw"></td>`
    + `<td><img src="file://${actual}" style="max-width:48vw"></td>`
    + `</tr></table>`;
}

/** Screenshot → <test>/<name>_Actual.png; assert byte-equality with the
 * <name>_Expected.png baseline. `taf promote` approves a new baseline. */
export async function compare(page: Page, name: string,
                              opts?: { mask?: Locator[] }): Promise<void> {
  const d = tafJournal.testDir();
  const actual = path.join(d, `${name}_Actual.png`);
  await page.screenshot({ path: actual, mask: opts?.mask });
  const expected = path.join(goldensDir(), `${name}_Expected.png`);
  if (!fs.existsSync(expected)) {
    ROWS.push({ name, status: "no-baseline", expected, actual });
    tafJournal.event("visual", { name, outcome: "no-baseline" });
    throw new Error(
      `no baseline for '${name}' — inspect ${actual} then \`taf promote\` approves it`);
  }
  if (fs.readFileSync(actual).equals(fs.readFileSync(expected))) {
    ROWS.push({ name, status: "ok", expected, actual });
    tafJournal.event("visual", { name, outcome: "ok" });
    return;
  }
  const diff = path.join(d, `${name}_Diff.html`);
  fs.writeFileSync(diff, diffHtml(name, expected, actual), "utf-8");
  ROWS.push({ name, status: "diff", expected, actual });
  tafJournal.event("visual", { name, outcome: "diff" });
  throw new Error(
    `screenshot '${name}' differs from the baseline — see ${diff}; ` +
    `\`taf promote\` approves the new image`);
}

/** The run's side-by-side report — visual-report.html in the run dir. */
export function writeReport(runDir: string): string | null {
  if (ROWS.length === 0) return null;
  const rows = ROWS.map(r =>
    `<tr><td>${r.name}</td><td>${r.status}</td>`
    + `<td><a href="file://${r.expected}">expected</a></td>`
    + `<td><a href="file://${r.actual}">actual</a></td></tr>`).join("");
  const p = path.join(runDir, "visual-report.html");
  fs.writeFileSync(p,
    `<!doctype html><meta charset=utf-8><title>visual report</title>`
    + `<h2>visual comparisons</h2><table border=1>`
    + `<tr><th>name</th><th>status</th><th>expected</th><th>actual</th></tr>${rows}</table>`,
    "utf-8");
  return p;
}

/** Approve Actual images under resultsDir as Expected baselines. */
export function promote(resultsDir: string, goldens: string): string[] {
  fs.mkdirSync(goldens, { recursive: true });
  const moved: string[] = [];
  const walk = (dir: string) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith("_Actual.png")) {
        const dst = path.join(goldens,
          e.name.slice(0, -"_Actual.png".length) + "_Expected.png");
        fs.copyFileSync(p, dst);
        moved.push(dst);
      }
    }
  };
  walk(resultsDir);
  return moved;
}
